cat > dryrun.mjs <<'EOF'
// Dry run: which open PRs could ever merge if main-branch-protection were switched on today?
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { parse } from "yaml";

const dir = process.argv[2] ?? "workflows";
const ruleset = JSON.parse(readFileSync("ruleset.json", "utf8"));
const prs = JSON.parse(readFileSync("prs.json", "utf8"));
const glob = (pattern) => new RegExp("^" + pattern.replace(/\*\*/g, "\0").replace(/\*/g, "[^/]*").replace(/\0/g, ".*") + "$");
const touches = (files, patterns) => files.some((f) => patterns.some((p) => glob(p).test(f)));

const files = readdirSync("workflows").map((name) => (existsSync(`${dir}/${name}`) ? `${dir}/${name}` : `workflows/${name}`));
const workflows = files.map((file) => parse(readFileSync(file, "utf8")));

// What GitHub would show on one PR: every check run, by the job's name.
const checksFor = (pr) => {
  const runs = [];
  for (const wf of workflows) {
    const paths = wf.on?.pull_request?.paths;
    if (paths && !touches(pr.files, paths)) continue; // filtered out: the workflow never starts, so its jobs never report
    const filters = {};
    for (const job of Object.values(wf.jobs)) {
      for (const step of job.steps ?? []) if (step.with?.filters) Object.assign(filters, parse(step.with.filters));
    }
    for (const [key, job] of Object.entries(wf.jobs)) {
      const name = job.name ?? key;
      const area = /outputs\.(\w+)\s*==\s*'true'/.exec(job.if ?? "")?.[1];
      if (area && !touches(pr.files, filters[area] ?? [])) runs.push({ name, status: "skipped" });
      else runs.push({ name, status: pr.failing?.includes(name) ? "failure" : "success" });
    }
  }
  return runs;
};

const required = ruleset.rules.find((r) => r.type === "required_status_checks").parameters.required_status_checks.map((c) => c.context);
const approvals = ruleset.rules.find((r) => r.type === "pull_request").parameters.required_approving_review_count;
let stuck = 0;
console.log(`Dry run of ${ruleset.name} (${dir}/) against ${prs.length} open PRs\n`);
for (const pr of prs) {
  const runs = checksFor(pr);
  const never = required.filter((ctx) => !runs.some((r) => r.name === ctx));
  const failing = required.filter((ctx) => runs.some((r) => r.name === ctx && r.status === "failure"));
  const verdict = never.length ? "STUCK  " : failing.length || pr.approvals < approvals ? "WAITING" : "READY  ";
  if (never.length) stuck += 1;
  const why = never.length ? `never reports: ${never.join(", ")}`
    : [failing.length && `fix: ${failing.join(", ")}`, pr.approvals < approvals && "needs 1 approval"].filter(Boolean).join("; ") || "can merge";
  console.log(`#${pr.number} ${verdict} ${pr.title.slice(0, 44).padEnd(44)}  ${why}`);
  console.log(`      checks seen: ${runs.filter((r) => r.name !== "check-changes").map((r) => `${r.name} (${r.status})`).join(", ") || "none"}`);
}
console.log(`\n${stuck} of ${prs.length} PRs could never merge. ${stuck ? "Do not switch the ruleset on yet." : "Safe to switch on: every PR can pass."}`);
EOF
